CREATE TABLE `action` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the action was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the action was updated',
  `type` longtext NOT NULL COMMENT 'Type of action',
  `model_id` int(11) NOT NULL,
  `name` varchar(254) NOT NULL,
  `description` longtext DEFAULT NULL COMMENT 'The description of the action',
  `parameters` longtext DEFAULT NULL COMMENT 'The saved parameters for this action',
  `parameter_mappings` longtext DEFAULT NULL COMMENT 'The saved parameter mappings for this action',
  `visualization_settings` longtext DEFAULT NULL COMMENT 'The UI visualization_settings for this action',
  `public_uuid` char(36) DEFAULT NULL COMMENT 'Unique UUID used to in publically-accessible links to this Action.',
  `made_public_by_id` int(11) DEFAULT NULL COMMENT 'The ID of the User who first publically shared this Action.',
  `creator_id` int(11) DEFAULT NULL COMMENT 'The user who created the action',
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_uuid` (`public_uuid`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_action_public_uuid` (`public_uuid`),
  KEY `fk_action_made_public_by_id` (`made_public_by_id`),
  KEY `idx_action_creator_id` (`creator_id`),
  KEY `fk_action_model_id` (`model_id`),
  CONSTRAINT `fk_action_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_action_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_action_model_id` FOREIGN KEY (`model_id`) REFERENCES `report_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An action is something you can do, such as run a readwrite query';
--;;
CREATE TABLE `ai_usage_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the LLM call was made',
  `source` varchar(100) NOT NULL COMMENT 'Origin of the LLM call, e.g. agent, slackbot, document-gen, intent-classification, example-question-gen, oss-sql-gen, semantic-search-embedding',
  `model` varchar(255) NOT NULL COMMENT 'Full model identifier, e.g. anthropic/claude-sonnet-4-20250514',
  `prompt_tokens` int(11) NOT NULL COMMENT 'Number of input/prompt tokens',
  `completion_tokens` int(11) NOT NULL COMMENT 'Number of output/completion tokens',
  `total_tokens` int(11) NOT NULL COMMENT 'Sum of prompt_tokens + completion_tokens',
  `user_id` int(11) DEFAULT NULL COMMENT 'Metabase user who triggered the call. NULL for system/background calls.',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'Snapshot of user tenant at request time. NULL for non-tenant users.',
  `conversation_id` varchar(36) DEFAULT NULL COMMENT 'Reference to metabot_conversation. NULL for non-conversational calls.',
  `profile_id` varchar(100) DEFAULT NULL COMMENT 'AI profile used, e.g. nlq, sql, slackbot',
  `request_id` varchar(36) DEFAULT NULL COMMENT 'UUID for correlating with Snowplow events',
  `ai_proxied` bit(1) DEFAULT NULL COMMENT 'Whether this call was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for rows created before this migration.',
  `cache_creation_tokens` int(11) DEFAULT NULL COMMENT 'Number of input tokens written to the provider prompt cache (Anthropic cache_creation_input_tokens).',
  `cache_read_tokens` int(11) DEFAULT NULL COMMENT 'Number of input tokens served from the provider prompt cache (Anthropic cache_read_input_tokens).',
  PRIMARY KEY (`id`),
  KEY `idx_ai_usage_log_user_id` (`user_id`),
  KEY `idx_ai_usage_log_conversation_id` (`conversation_id`),
  KEY `idx_ai_usage_log_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Universal ledger for all LLM API call usage tracking';
--;;
CREATE TABLE `analysis_finding` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `analyzed_entity_type` varchar(254) NOT NULL COMMENT 'The type of the analyzed entity',
  `analyzed_entity_id` int(11) NOT NULL COMMENT 'The ID of the analyzed entity',
  `analysis_version` int(11) NOT NULL COMMENT 'The version of the analysis that was performed',
  `analyzed_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the analysis was performed',
  `result` bit(1) NOT NULL COMMENT 'The result of the analysis - true for passed, false for failed',
  `stale` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the entity needs re-analysis due to upstream changes',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_analysis_finding` (`analyzed_entity_type`,`analyzed_entity_id`),
  KEY `idx_analyzed_entity` (`analyzed_entity_type`,`analyzed_entity_id`),
  KEY `idx_analysis_result` (`result`),
  KEY `idx_analysis_finding_stale` (`stale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Findings from analysis of cards, transforms, dashboards, etc.';
--;;
CREATE TABLE `analysis_finding_error` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `analyzed_entity_type` varchar(254) NOT NULL COMMENT 'The type of the analyzed entity (card, transform, segment, etc.)',
  `analyzed_entity_id` int(11) NOT NULL COMMENT 'The ID of the analyzed entity',
  `error_type` varchar(254) NOT NULL COMMENT 'The type of error (missing-column, missing-table-alias, duplicate-column, syntax-error, validation-exception-error)',
  `error_detail` varchar(254) DEFAULT NULL COMMENT 'Additional error details (e.g., column name, alias name, error message)',
  `source_entity_type` varchar(254) DEFAULT NULL COMMENT 'The type of the source entity causing the error (table, card, etc.)',
  `source_entity_id` int(11) DEFAULT NULL COMMENT 'The ID of the source entity causing the error',
  PRIMARY KEY (`id`),
  KEY `idx_analysis_finding_error_source` (`source_entity_type`,`source_entity_id`),
  KEY `idx_analysis_finding_error_analyzed` (`analyzed_entity_type`,`analyzed_entity_id`),
  KEY `idx_analysis_finding_error_type` (`error_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Individual validation errors from analysis with source entity information';
--;;
CREATE TABLE `api_key` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'The ID of the API Key itself',
  `user_id` int(11) DEFAULT NULL,
  `key` varchar(254) NOT NULL COMMENT 'The hashed API key',
  `key_prefix` varchar(7) NOT NULL COMMENT 'The first 7 characters of the unhashed key',
  `creator_id` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp when the key was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp when the key was last updated',
  `name` varchar(254) NOT NULL COMMENT 'The user-defined name of the API key.',
  `updated_by_id` int(11) NOT NULL COMMENT 'The ID of the user that last updated this API key',
  `scope` varchar(64) DEFAULT NULL COMMENT 'The scope of the API key, if applicable',
  PRIMARY KEY (`id`),
  UNIQUE KEY `key_prefix` (`key_prefix`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_api_key_created_by` (`creator_id`),
  KEY `idx_api_key_user_id` (`user_id`),
  KEY `idx_api_key_updated_by_id` (`updated_by_id`),
  CONSTRAINT `fk_api_key_created_by_user_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_api_key_updated_by_id_user_id` FOREIGN KEY (`updated_by_id`) REFERENCES `core_user` (`id`),
  CONSTRAINT `fk_api_key_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An API Key';
--;;
CREATE TABLE `application_permissions_revision` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `before` longtext NOT NULL COMMENT 'Serialized JSON of the permission graph before the changes.',
  `after` longtext NOT NULL COMMENT 'Serialized JSON of the changes in permission graph.',
  `user_id` int(11) NOT NULL COMMENT 'The ID of the admin who made this set of changes.',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `remark` longtext DEFAULT NULL COMMENT 'Optional remarks explaining why these changes were made.',
  PRIMARY KEY (`id`),
  KEY `fk_general_permissions_revision_user_id` (`user_id`),
  CONSTRAINT `fk_general_permissions_revision_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to keep track of changes made to general permissions.';
--;;
CREATE TABLE `audit_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `topic` varchar(32) NOT NULL COMMENT 'The topic of a given audit event',
  `timestamp` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'The time an event was recorded',
  `end_timestamp` timestamp(6) NULL DEFAULT NULL COMMENT 'The time an event ended, if applicable',
  `user_id` int(11) DEFAULT NULL COMMENT 'The user who performed an action or triggered an event',
  `model` varchar(32) DEFAULT NULL COMMENT 'The name of the model this event applies to (e.g. Card, Dashboard), if applicable',
  `model_id` int(11) DEFAULT NULL COMMENT 'The ID of the model this event applies to, if applicable',
  `details` longtext NOT NULL COMMENT 'A JSON map with metadata about the event',
  PRIMARY KEY (`id`),
  KEY `idx_audit_log_model_model_id` (`model`,`model_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to store application events for auditing use cases';
--;;
CREATE TABLE `auth_identity` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Integer primary key',
  `user_id` int(11) NOT NULL COMMENT 'Foreign key to core_user',
  `provider` varchar(50) NOT NULL COMMENT 'Authentication provider type (password, google, ldap, saml, jwt, support)',
  `credentials` longtext DEFAULT NULL COMMENT 'JSON object containing provider-specific credentials',
  `metadata` longtext DEFAULT NULL COMMENT 'JSON object containing provider-specific metadata',
  `provider_id` varchar(255) DEFAULT NULL COMMENT 'Provider-specific identifier (email for password/Google, DN for LDAP, subject for SAML/JWT)',
  `last_used_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp of last successful authentication',
  `expires_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Timestamp when this authentication method expires (null = never expires)',
  `created_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'Timestamp when this identity was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'Timestamp when this identity was last updated',
  `confirmed_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When this identity was confirmed (e.g. MFA enrollment completed). Null = unconfirmed.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_auth_identity_user_provider` (`user_id`,`provider`),
  KEY `idx_auth_identity_user_id` (`user_id`),
  KEY `idx_auth_identity_provider` (`provider`),
  KEY `idx_auth_identity_provider_id` (`provider_id`),
  KEY `idx_auth_identity_provider_provider_id` (`provider`,`provider_id`),
  CONSTRAINT `fk_auth_identity_core_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores authentication credentials for users. A user can have multiple auth identities.';
--;;
