CREATE TABLE `comment` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Primary key for comment table',
  `parent_comment_id` int(11) DEFAULT NULL COMMENT 'ID of the parent comment for threading (null for root comments)',
  `target_type` varchar(50) NOT NULL DEFAULT 'document' COMMENT 'Type of entity being commented on',
  `target_id` int(11) NOT NULL COMMENT 'ID of the entity being commented on',
  `child_target_id` longtext DEFAULT NULL COMMENT 'Sub-entity ID (e.g., document block node ID)',
  `creator_id` int(11) NOT NULL COMMENT 'User who created this comment',
  `content` longtext NOT NULL COMMENT 'The comment content',
  `is_resolved` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this comment thread is resolved',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when comment was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when comment was last updated',
  `deleted_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Soft delete timestamp (null if not deleted)',
  `content_html` longtext DEFAULT NULL COMMENT 'HTML-rendered version of the comment content',
  PRIMARY KEY (`id`),
  KEY `idx_comment_entity` (`target_type`,`target_id`),
  KEY `idx_comment_creator_id` (`creator_id`),
  KEY `idx_comment_parent_comment_id` (`parent_comment_id`),
  CONSTRAINT `fk_comment_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_comment_parent_comment_id` FOREIGN KEY (`parent_comment_id`) REFERENCES `comment` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Comments on various entities (documents, dashboards, etc.)';
--;;
CREATE TABLE `comment_reaction` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Primary key for comment_reaction table',
  `comment_id` int(11) NOT NULL COMMENT 'ID of the comment being reacted to',
  `user_id` int(11) NOT NULL COMMENT 'User who added this reaction',
  `emoji` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when reaction was added',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_comment_emoji` (`comment_id`,`user_id`,`emoji`),
  KEY `fk_comment_reaction_user_id` (`user_id`),
  KEY `idx_comment_reaction_comment_id` (`comment_id`),
  CONSTRAINT `fk_comment_reaction_comment_id` FOREIGN KEY (`comment_id`) REFERENCES `comment` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_comment_reaction_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store reactions (emojis) on comments';
--;;
CREATE TABLE `connection_impersonations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `db_id` int(11) NOT NULL COMMENT 'ID of the database this connection impersonation policy affects',
  `group_id` int(11) NOT NULL COMMENT 'ID of the permissions group this connection impersonation policy affects',
  `attribute` longtext DEFAULT NULL COMMENT 'User attribute associated with the database role to use for this connection impersonation policy',
  PRIMARY KEY (`id`),
  UNIQUE KEY `conn_impersonation_unique_group_id_db_id` (`group_id`,`db_id`),
  KEY `idx_conn_impersonations_db_id` (`db_id`),
  KEY `idx_conn_impersonations_group_id` (`group_id`),
  CONSTRAINT `fk_conn_impersonation_db_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_conn_impersonation_group_id` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table for holding connection impersonation policies';
--;;
CREATE TABLE `content_translation` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `locale` varchar(5) NOT NULL COMMENT 'Locale',
