CREATE TABLE `custom_viz_plugin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `identifier` varchar(254) NOT NULL COMMENT 'Unique identifier used as visualization display type. Comes from the manifest "name" field.',
  `display_name` varchar(254) NOT NULL COMMENT 'Human-readable name from the plugin manifest',
  `status` varchar(32) NOT NULL COMMENT 'Plugin status - active or error',
  `error_message` longtext DEFAULT NULL COMMENT 'Last error message if status is error',
  `bundle` longblob DEFAULT NULL,
  `bundle_hash` varchar(64) DEFAULT NULL COMMENT 'SHA-256 hex of the uploaded bundle, used as the on-disk cache key and HTTP ETag. Null for dev-only plugins.',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'Timestamp when the plugin was registered',
  `updated_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'Timestamp when the plugin was last updated',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the plugin is enabled for use in dashboards and questions',
  `icon` varchar(254) DEFAULT NULL COMMENT 'Icon from plugin manifest - asset path resolved to a URL',
  `manifest` longtext DEFAULT NULL COMMENT 'JSON manifest from metabase-plugin.json in the uploaded bundle',
  `metabase_version` varchar(254) DEFAULT NULL COMMENT 'Metabase version range requirement from manifest (e.g. ">=1.59 <1.62")',
  `dev_bundle_url` varchar(1024) DEFAULT NULL COMMENT 'Dev server URL for hot-reload development (e.g. http://localhost:5174)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `identifier` (`identifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores registered custom visualization plugins uploaded as zip bundles';
--;;
