CREATE TABLE `data_complexity_score` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fingerprint` varchar(512) NOT NULL COMMENT 'Fingerprint of the scoring inputs (formula version, synonym threshold, embedding model)',
  `score_data` longtext NOT NULL COMMENT 'JSON-serialized complexity score response returned by the data-complexity-score endpoint',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this score snapshot was computed and stored',
  `source` varchar(255) NOT NULL DEFAULT 'appdb' COMMENT 'Provenance — "appdb" for cron/API/CLI-from-appdb, or "representation:<digest>" for CLI runs that scored a representation directory.',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only snapshots of the computed Data Complexity Score shown in the Metabot overview UI';
--;;
CREATE TABLE `data_edit_undo_chain` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `batch_num` int(11) NOT NULL COMMENT 'Batch number for grouped changes (global increment)',
  `table_id` int(11) NOT NULL COMMENT 'Reference to the table being modified',
  `row_pk` longtext NOT NULL COMMENT 'PK of the row being modified, potentially composite. Stored as a sorted JSON map.',
  `user_id` int(11) NOT NULL COMMENT 'ID of the user who made the change',
  `scope` longtext NOT NULL COMMENT 'Identifies where the changes were made from',
  `undoable` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Identifies whether a change can be undo',
  `raw_before` longtext DEFAULT NULL COMMENT 'Value of the field before the change',
  `raw_after` longtext DEFAULT NULL COMMENT 'Value of the field after the change',
  `undone` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this change has been undone',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the change was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the change was updated',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store the state necessary to power undo / redo.';
--;;
CREATE TABLE `data_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'The ID of the permission',
  `group_id` int(11) NOT NULL COMMENT 'The ID of the associated permission group',
  `perm_type` varchar(64) NOT NULL COMMENT 'The type of the permission (e.g. "data", "collection", "download"...)',
  `db_id` int(11) NOT NULL COMMENT 'A database ID, for DB and table-level permissions',
  `schema_name` varchar(254) DEFAULT NULL COMMENT 'A schema name, for table-level permissions',
  `table_id` int(11) DEFAULT NULL COMMENT 'A table ID',
  `perm_value` varchar(64) NOT NULL COMMENT 'The value this permission is set to.',
  `unique_perms_helper` int(11) GENERATED ALWAYS AS (coalesce(`table_id`,-1)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_data_permissions` (`group_id`,`perm_type`,`db_id`,`unique_perms_helper`),
  KEY `idx_data_permissions_table_id` (`table_id`),
  KEY `idx_data_permissions_db_id` (`db_id`),
  KEY `idx_data_permissions_group_id` (`group_id`),
  KEY `idx_data_permissions_group_id_db_id_perm_value` (`group_id`,`db_id`,`perm_value`),
  KEY `idx_data_permissions_group_id_db_id_table_id_perm_value` (`group_id`,`db_id`,`table_id`,`perm_value`),
  CONSTRAINT `fk_data_permissions_ref_db_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_permissions_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_data_permissions_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to store database and table permissions';
--;;
CREATE TABLE `db_router` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `database_id` int(11) NOT NULL COMMENT 'The ID of the database this is for.',
  `user_attribute` varchar(254) NOT NULL COMMENT 'The user attribute used to redirect users to a different database.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `database_id` (`database_id`),
  CONSTRAINT `fk_db_router_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Configuration for Database Routers. Currently just holds which user attribute each\nconfigured router database should use to choose a mirror database to route to.\n';
--;;
CREATE TABLE `dependency` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `from_entity_type` varchar(20) NOT NULL COMMENT 'The type of the dependent entity',
  `from_entity_id` int(11) NOT NULL COMMENT 'The ID of the dependent entity',
  `to_entity_type` varchar(20) NOT NULL COMMENT 'The type of the entity depended on',
  `to_entity_id` int(11) NOT NULL COMMENT 'The ID of the entity depended on',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_dependency` (`from_entity_type`,`from_entity_id`,`to_entity_type`,`to_entity_id`),
  KEY `idx_dependency_from` (`from_entity_type`,`from_entity_id`),
  KEY `idx_dependency_to` (`to_entity_type`,`to_entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to track dependencies between Metabase entities';
--;;
CREATE TABLE `dependency_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(254) NOT NULL COMMENT 'The type of the entity (card, transform, snippet, etc.)',
  `entity_id` int(11) NOT NULL COMMENT 'The ID of the entity',
  `dependency_analysis_version` smallint(6) NOT NULL DEFAULT 0 COMMENT 'Version of the dependency analysis that was performed',
  `stale` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the entity needs dependency recalculation',
  `fail_count` int(11) NOT NULL DEFAULT 0 COMMENT 'Number of consecutive failed dependency calculation attempts',
  `next_retry_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Earliest time at which a failed entity can be retried (null means immediately processable)',
  `terminal` bit(1) NOT NULL DEFAULT b'0' COMMENT 'True when the entity has exceeded max retries and should not be retried until modified',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_dependency_status` (`entity_type`,`entity_id`),
  KEY `idx_dependency_status_stale` (`stale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tracks dependency calculation status for entities, analogous to analysis_finding';
--;;
CREATE TABLE `dimension` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `field_id` int(11) NOT NULL COMMENT 'ID of the field this dimension row applies to',
  `name` varchar(254) NOT NULL COMMENT 'Short description used as the display name of this new column',
  `type` varchar(254) NOT NULL COMMENT 'Either internal for a user defined remapping or external for a foreign key based remapping',
  `human_readable_field_id` int(11) DEFAULT NULL COMMENT 'Only used with external type remappings. Indicates which field on the FK related table to use for display',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_dimension_field_id` (`field_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_dimension_displayfk_ref_field_id` (`human_readable_field_id`),
  KEY `idx_dimension_field_id` (`field_id`),
  CONSTRAINT `fk_dimension_displayfk_ref_field_id` FOREIGN KEY (`human_readable_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dimension_ref_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores references to alternate views of existing fields, such as remapping an integer to a description, like an enum';
--;;
CREATE TABLE `document` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext NOT NULL COMMENT 'Document name',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the document was created',
  `document` longtext DEFAULT NULL COMMENT 'content of the document',
  `content_type` longtext NOT NULL COMMENT 'the content_type of the document column',
  `creator_id` int(11) NOT NULL COMMENT 'User who created this document',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the document was updated',
  `collection_id` int(11) DEFAULT NULL COMMENT 'What collection I live in. Null if it''s Our Analytics.',
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Has this document been archived?',
  `archived_directly` bit(1) DEFAULT b'0' COMMENT 'Was this thing trashed directly',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity',
  `last_viewed_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp of when this document was last viewed',
  `view_count` int(11) NOT NULL DEFAULT 0 COMMENT 'Keeps a running count of document views',
  `collection_position` int(11) DEFAULT NULL COMMENT 'Collection position used for pinning documents. Higher numbers = pinned, null = not pinned.',
  `public_uuid` char(36) DEFAULT NULL COMMENT 'UUID for publicly-accessible version of this document',
  `made_public_by_id` int(11) DEFAULT NULL COMMENT 'ID of the user who made this document public',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  UNIQUE KEY `idx_document_public_uuid` (`public_uuid`),
  KEY `idx_document_creator_id` (`creator_id`),
  KEY `idx_document_collection_id` (`collection_id`),
  KEY `idx_document_made_public_by_id` (`made_public_by_id`),
  CONSTRAINT `fk_document_made_public_by_id` FOREIGN KEY (`made_public_by_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_document_ref_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_document_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Documents table';
--;;
CREATE TABLE `document_bookmark` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `user_id` int(11) NOT NULL COMMENT 'User who bookmarked the document',
  `document_id` int(11) NOT NULL COMMENT 'The document that was bookmarked',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp when the bookmark was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_document_bookmark_user_document_unique` (`user_id`,`document_id`),
  KEY `idx_document_bookmark_user_id` (`user_id`),
  KEY `idx_document_bookmark_document_id` (`document_id`),
  CONSTRAINT `fk_document_bookmark_document_id` FOREIGN KEY (`document_id`) REFERENCES `document` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_document_bookmark_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store user bookmarks for documents';
--;;
CREATE TABLE `embedding_theme` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity',
  `name` varchar(255) NOT NULL COMMENT 'Name of the embed theme',
  `settings` longtext NOT NULL COMMENT 'JSON object of theme settings',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when the theme was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when the theme was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores themes created via the embedding theme editor';
--;;
CREATE TABLE `field_usage` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `field_id` int(11) NOT NULL COMMENT 'ID of the field',
  `query_execution_id` int(11) NOT NULL COMMENT 'referenced query execution',
  `used_in` varchar(25) NOT NULL COMMENT 'which part of the query the field was used in',
  `filter_op` varchar(25) DEFAULT NULL COMMENT 'filter''s operator that applied to the field',
  `aggregation_function` varchar(25) DEFAULT NULL COMMENT 'the aggregation function that field applied to',
  `breakout_temporal_unit` varchar(25) DEFAULT NULL COMMENT 'temporal unit options of the breakout',
  `breakout_binning_strategy` varchar(25) DEFAULT NULL COMMENT 'the strategy of breakout',
  `breakout_binning_num_bins` int(11) DEFAULT NULL COMMENT 'The numbin option of breakout',
  `breakout_binning_bin_width` int(11) DEFAULT NULL COMMENT 'The numbin option of breakout',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The time a field usage was recorded',
  PRIMARY KEY (`id`),
  KEY `idx_field_usage_field_id` (`field_id`),
  KEY `idx_field_usage_query_execution_id` (`query_execution_id`),
  CONSTRAINT `fk_field_usage_field_id_metabase_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_field_usage_query_execution_id` FOREIGN KEY (`query_execution_id`) REFERENCES `query_execution` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Used to store field usage during query execution';
--;;
CREATE TABLE `glossary` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Primary key identifier for glossary entries',
  `term` varchar(255) NOT NULL COMMENT 'The glossary term or phrase being defined',
  `definition` longtext NOT NULL COMMENT 'The detailed definition or explanation of the term',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when comment was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp when comment was last updated',
  `creator_id` int(11) NOT NULL DEFAULT 13371338 COMMENT 'User who created this glossary entry',
  PRIMARY KEY (`id`),
  UNIQUE KEY `term` (`term`),
  KEY `idx_glossary_creator_id` (`creator_id`),
  CONSTRAINT `fk_glossary_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store glossary terms and their definitions';
--;;
CREATE TABLE `health_inspector_runs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `message` longtext DEFAULT NULL COMMENT 'A message to show to the instance admin.',
  `check_name` varchar(254) NOT NULL COMMENT 'The name of the check',
  `run_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When it was run',
  `health` int(11) NOT NULL COMMENT 'Health as a percentage out of 100',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Records status of health inspector runs over time';
--;;
CREATE TABLE `http_action` (
  `action_id` int(11) NOT NULL COMMENT 'The related action',
  `template` longtext NOT NULL COMMENT 'A template that defines method,url,body,headers required to make an api call',
  `response_handle` longtext DEFAULT NULL COMMENT 'A program to take an api response and transform to an appropriate response for emitters',
  `error_handle` longtext DEFAULT NULL COMMENT 'A program to take an api response to determine if an error occurred',
  PRIMARY KEY (`action_id`),
  CONSTRAINT `fk_http_action_ref_action_id` FOREIGN KEY (`action_id`) REFERENCES `action` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An http api call type of action';
--;;
CREATE TABLE `implicit_action` (
  `action_id` int(11) NOT NULL COMMENT 'The associated action',
  `kind` longtext NOT NULL COMMENT 'The kind of implicit action create/update/delete',
  PRIMARY KEY (`action_id`),
  CONSTRAINT `fk_implicit_action_action_id` FOREIGN KEY (`action_id`) REFERENCES `action` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='An action with dynamic parameters based on the underlying model';
--;;
CREATE TABLE `label` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(254) NOT NULL,
  `slug` varchar(254) NOT NULL,
  `icon` varchar(128) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_label_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `login_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `timestamp` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this login occurred.',
  `user_id` int(11) NOT NULL COMMENT 'ID of the User that logged in.',
  `session_id` varchar(254) DEFAULT NULL COMMENT 'ID of the Session created by this login if one is currently active. NULL if Session is no longer active.',
  `device_id` char(36) NOT NULL COMMENT 'Cookie-based unique identifier for the device/browser the user logged in from.',
  `device_description` longtext DEFAULT NULL,
  `ip_address` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_timestamp` (`timestamp`),
  KEY `idx_user_id_timestamp` (`user_id`,`timestamp`),
  KEY `idx_user_id_device_id` (`user_id`,`device_id`),
  CONSTRAINT `fk_login_history_session_id` FOREIGN KEY (`session_id`) REFERENCES `core_session` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_login_history_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Keeps track of various logins for different users and additional info such as location and device';
--;;
CREATE TABLE `mcp_query_handle` (
  `id` varchar(36) NOT NULL COMMENT 'Handle UUID; returned to the iframe and threaded through to the MCP tool call',
  `mcp_session_id` varchar(254) NOT NULL,
  `core_session_id` varchar(254) DEFAULT NULL COMMENT 'core_session.id when one has been materialized; cascade-deletes with the session',
  `encoded_query` longtext NOT NULL COMMENT 'Base64-encoded MBQL query payload',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'When this handle was stored; useful for debugging and future TTL cleanup',
  `prompt` longtext DEFAULT NULL COMMENT 'The user''s original prompt used to construct the query; nullable for drill-through handles',
  PRIMARY KEY (`id`),
  KEY `idx_mcp_query_handle_mcp_session_id` (`mcp_session_id`),
  KEY `idx_mcp_query_handle_core_session_id` (`core_session_id`),
  CONSTRAINT `fk_mcp_query_handle_ref_core_session` FOREIGN KEY (`core_session_id`) REFERENCES `core_session` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Server-side store for encoded MBQL query payloads referenced by MCP tool calls';
--;;
CREATE TABLE `measure` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `table_id` int(11) NOT NULL COMMENT 'Foreign key to metabase_table',
  `creator_id` int(11) NOT NULL COMMENT 'Foreign key to core_user who created this measure',
  `name` varchar(254) NOT NULL COMMENT 'Name of the measure',
  `description` longtext DEFAULT NULL COMMENT 'Optional description of the measure',
  `archived` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether the measure has been archived',
  `definition` longtext NOT NULL COMMENT 'JSON MBQL query containing the aggregation definition',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'Timestamp when this measure was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'Timestamp when this measure was last updated',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity',
  `dimensions` longtext DEFAULT NULL COMMENT 'JSON array of persisted dimension definitions (id, display-name, types)',
  `dimension_mappings` longtext DEFAULT NULL COMMENT 'JSON array of dimension-to-field mappings (dimension-id, target, table-id)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_measure_table_id` (`table_id`),
  KEY `idx_measure_creator_id` (`creator_id`),
  CONSTRAINT `fk_measure_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_measure_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stores saved aggregation expressions tied to tables';
--;;
CREATE TABLE `metabase_cluster_lock` (
  `lock_name` varchar(254) NOT NULL COMMENT 'a single column that can be used to a lock across a cluster',
  PRIMARY KEY (`lock_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to allow metabase instances to take locks across a cluster';
--;;
CREATE TABLE `metabase_database` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `name` varchar(254) NOT NULL,
  `description` longtext DEFAULT NULL,
  `details` longtext NOT NULL,
  `engine` varchar(254) NOT NULL,
  `is_sample` bit(1) NOT NULL DEFAULT b'0',
  `is_full_sync` bit(1) NOT NULL DEFAULT b'1',
  `points_of_interest` longtext DEFAULT NULL,
  `caveats` longtext DEFAULT NULL,
  `metadata_sync_schedule` varchar(254) NOT NULL DEFAULT '0 50 * * * ? *' COMMENT 'The cron schedule string for when this database should undergo the metadata sync process (and analysis for new fields).',
  `cache_field_values_schedule` varchar(254) DEFAULT NULL,
  `timezone` varchar(254) DEFAULT NULL COMMENT 'Timezone identifier for the database, set by the sync process',
  `is_on_demand` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether we should do On-Demand caching of FieldValues for this DB. This means FieldValues are updated when their Field is used in a Dashboard or Card param.',
  `auto_run_queries` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether to automatically run queries when doing simple filtering and summarizing in the Query Builder.',
  `refingerprint` bit(1) DEFAULT NULL COMMENT 'Whether or not to enable periodic refingerprinting for this Database.',
  `cache_ttl` int(11) DEFAULT NULL COMMENT 'Granular cache TTL for specific database.',
  `initial_sync_status` varchar(32) NOT NULL DEFAULT 'complete' COMMENT 'String indicating whether a database has completed its initial sync and is ready to use',
  `creator_id` int(11) DEFAULT NULL COMMENT 'ID of the admin who added the database',
  `settings` longtext DEFAULT NULL COMMENT 'Serialized JSON containing Database-local Settings for this Database',
  `dbms_version` longtext DEFAULT NULL COMMENT 'A JSON object describing the flavor and version of the DBMS.',
  `is_audit` bit(1) NOT NULL DEFAULT b'0',
  `uploads_enabled` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether uploads are enabled for this database',
  `uploads_schema_name` longtext DEFAULT NULL COMMENT 'The schema name for uploads',
  `uploads_table_prefix` longtext DEFAULT NULL COMMENT 'The prefix for upload table names',
  `is_attached_dwh` bit(1) NOT NULL DEFAULT b'0' COMMENT 'This is an attached data warehouse, do not serialize it and hide its details from the UI',
  `router_database_id` int(11) DEFAULT NULL COMMENT 'The ID of the primary database for this mirror database.',
  `provider_name` varchar(100) DEFAULT NULL COMMENT 'The name of the hosting provider for the database (e.g., AWS RDS, Azure).',
  `write_data_details` longtext DEFAULT NULL COMMENT 'Encrypted JSON containing connection details for write operations (transforms, etc.)',
  `admin_details` longtext DEFAULT NULL COMMENT 'Encrypted JSON containing connection details for admin (highest-privilege) operations such as DDL and ownership changes',
  `is_stub` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Placeholder database created during deserialization; cleared when real details are supplied and the connection test passes',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_metabase_database_router_database_id_name` (`router_database_id`,`name`),
  KEY `fk_database_creator_id` (`creator_id`),
  CONSTRAINT `fk_database_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_metabase_database_metabase_database_id` FOREIGN KEY (`router_database_id`) REFERENCES `metabase_database` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_field` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `base_type` varchar(255) NOT NULL,
  `semantic_type` varchar(255) DEFAULT NULL,
  `active` bit(1) NOT NULL DEFAULT b'1',
  `description` longtext DEFAULT NULL,
  `preview_display` bit(1) NOT NULL DEFAULT b'1',
  `position` int(11) NOT NULL DEFAULT 0,
  `table_id` int(11) NOT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `display_name` varchar(254) DEFAULT NULL,
  `visibility_type` varchar(32) NOT NULL DEFAULT 'normal',
  `fk_target_field_id` int(11) DEFAULT NULL,
  `last_analyzed` timestamp(6) NULL DEFAULT NULL,
  `points_of_interest` longtext DEFAULT NULL,
  `caveats` longtext DEFAULT NULL,
  `fingerprint` longtext DEFAULT NULL,
  `fingerprint_version` int(11) NOT NULL DEFAULT 0 COMMENT 'The version of the fingerprint for this Field. Used so we can keep track of which Fields need to be analyzed again when new things are added to fingerprints.',
  `database_type` longtext DEFAULT NULL,
  `has_field_values` longtext DEFAULT NULL,
  `settings` longtext DEFAULT NULL,
  `database_position` int(11) NOT NULL DEFAULT 0,
  `custom_position` int(11) NOT NULL DEFAULT 0,
  `effective_type` varchar(255) DEFAULT NULL COMMENT 'The effective type of the field after any coercions.',
  `coercion_strategy` varchar(255) DEFAULT NULL COMMENT 'A strategy to coerce the base_type into the effective_type.',
  `nfc_path` varchar(254) DEFAULT NULL COMMENT 'Nested field column paths, flattened',
  `database_required` bit(1) NOT NULL DEFAULT b'0',
  `json_unfolding` bit(1) NOT NULL DEFAULT b'0',
  `database_is_auto_increment` bit(1) NOT NULL DEFAULT b'0',
  `database_indexed` bit(1) DEFAULT NULL,
  `database_partitioned` bit(1) DEFAULT NULL,
  `is_defective_duplicate` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Indicates whether column is a defective duplicate field that should never have been created.',
  `unique_field_helper` int(11) GENERATED ALWAYS AS (case when `is_defective_duplicate` = 1 then NULL else case when `parent_id` is null then 0 else `parent_id` end end) STORED,
  `database_is_pk` bit(1) DEFAULT NULL COMMENT 'Whether or not the field is part of the primary key (not user editable like semantic_type)',
  `database_is_nullable` bit(1) DEFAULT NULL COMMENT 'Whether or not the field will accept nulls',
  `database_is_generated` bit(1) DEFAULT NULL COMMENT 'Whether or not the column is computed and will not accept writes',
  `database_default` longtext DEFAULT NULL COMMENT 'The dialect specific column default expression',
  `dimension_interestingness` double DEFAULT NULL COMMENT 'Interestingness score (0.0-1.0) for this field when treated as a dimension in a metric.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_field` (`name`,`table_id`,`unique_field_helper`),
  KEY `idx_field_table_id` (`table_id`),
  KEY `idx_field_parent_id` (`parent_id`),
  KEY `idx_field_fk_target_field_id` (`fk_target_field_id`),
  CONSTRAINT `fk_field_fk_target_ref_field_id` FOREIGN KEY (`fk_target_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_field_parent_ref_field_id` FOREIGN KEY (`parent_id`) REFERENCES `metabase_field` (`id`),
  CONSTRAINT `fk_field_ref_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_field_import` (
  `source_id` int(11) NOT NULL COMMENT 'Wire :id — source appdb''s metabase_field.id. Unique within one file.',
  `source_table_id` int(11) NOT NULL COMMENT 'Wire :table_id — references metabase_table_import.source_id within the same file.',
  `source_parent_id` int(11) DEFAULT NULL COMMENT 'Wire :parent_id — references another metabase_field_import.source_id within the same file. NULL for top-level fields.',
  `source_fk_target_id` int(11) DEFAULT NULL COMMENT 'Wire :fk_target_field_id — references another metabase_field_import.source_id. NULL for non-FK fields.',
  `name` varchar(254) NOT NULL COMMENT 'Wire :name — field''s natural-key name component (within its parent + table).',
  `base_type` varchar(254) NOT NULL COMMENT 'Wire :base_type — clobbered onto metabase_field.base_type on merge.',
  `database_type` varchar(254) NOT NULL COMMENT 'Wire :database_type — clobbered onto metabase_field.database_type on merge.',
  `effective_type` varchar(254) DEFAULT NULL COMMENT 'NULL when wire row omitted it (≡ base_type). Importer treats NULL as base_type on INSERT; leaves target alone on UPDATE.',
  `semantic_type` varchar(254) DEFAULT NULL COMMENT 'Wire :semantic_type — clobbered onto metabase_field.semantic_type on merge.',
  `coercion_strategy` varchar(254) DEFAULT NULL COMMENT 'Wire :coercion_strategy — clobbered onto metabase_field.coercion_strategy on merge.',
  `description` longtext DEFAULT NULL COMMENT 'Wire :description — clobbered onto metabase_field.description on merge.',
  `nfc_path` longtext DEFAULT NULL COMMENT 'NULL for empty/absent paths, JSON-encoded array string otherwise — same encoding as metabase_field.nfc_path.',
  `depth` int(11) DEFAULT NULL COMMENT 'Populated once after drain by the depth-tagging step. 0 = root (no parent, no fk_target). Higher = max(parent depth, fk_target depth) + 1. NULL after depth-tagging means a cycle in the file''s reference graph.',
  `target_id` int(11) DEFAULT NULL COMMENT 'Resolved per-depth-level by natural-key match against metabase_field. NULL means no live row matches; row is an insert candidate at this depth.',
  `target_table_id` int(11) DEFAULT NULL COMMENT 'Populated from the table-resolve step before the depth walk starts. Joined-through from metabase_table_import.target_id.',
  `target_parent_id` int(11) DEFAULT NULL COMMENT 'Populated per-depth-level by self-join on source_parent_id → another row''s target_id.',
  `target_fk_target_id` int(11) DEFAULT NULL COMMENT 'Populated per-depth-level by self-join on source_fk_target_id → another row''s target_id.',
  PRIMARY KEY (`source_id`),
  KEY `idx_mfi_depth` (`depth`),
  KEY `idx_mfi_target_id` (`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Staging table for the metadata file importer''s fields phase. Drained outside the merge txn, depth-tagged, then merged into metabase_field level by level inside the txn.';
--;;
CREATE TABLE `metabase_field_user_settings` (
  `field_id` int(11) NOT NULL COMMENT 'The related Field',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the user setting was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the user setting was updated',
  `semantic_type` varchar(254) DEFAULT NULL COMMENT 'User-set semantic_type for the Field',
  `description` longtext DEFAULT NULL COMMENT 'User-set description for the Field',
  `display_name` varchar(254) DEFAULT NULL COMMENT 'User-set display_name for the Field',
  `visibility_type` varchar(32) DEFAULT NULL COMMENT 'User-set visibility_type for the Field',
  `fk_target_field_id` int(11) DEFAULT NULL COMMENT 'User-set fk_target_field_id for the Field',
  `has_field_values` longtext DEFAULT NULL COMMENT 'User-set has_field_values for the Field',
  `effective_type` varchar(255) DEFAULT NULL COMMENT 'User-set effective_type for the Field',
  `coercion_strategy` varchar(255) DEFAULT NULL COMMENT 'User-set coercion_strategy for the Field',
  `caveats` longtext DEFAULT NULL COMMENT 'User-set caveats for the Field',
  `points_of_interest` longtext DEFAULT NULL COMMENT 'User-set points_of_interest for the Field',
  `nfc_path` varchar(254) DEFAULT NULL COMMENT 'User-set nfc_path for the Field',
  `json_unfolding` bit(1) DEFAULT NULL COMMENT 'User-set json_unfolding for the Field',
  `settings` longtext DEFAULT NULL COMMENT 'User-set settings for the Field',
  PRIMARY KEY (`field_id`),
  KEY `idx_field_user_settings_fk_target_field_id` (`fk_target_field_id`),
  CONSTRAINT `fk_field_user_setting_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_field_user_settings_fk_target_ref_field_id` FOREIGN KEY (`fk_target_field_id`) REFERENCES `metabase_field` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Mirror table of metabase_field to keep track of user-set values (only settable fields are mirrored)';
--;;
CREATE TABLE `metabase_fieldvalues` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `values` longtext DEFAULT NULL,
  `human_readable_values` longtext DEFAULT NULL,
  `field_id` int(11) NOT NULL,
  `has_more_values` bit(1) DEFAULT b'0',
  `type` varchar(32) NOT NULL DEFAULT 'full' COMMENT 'Type of FieldValues',
  `hash_key` longtext DEFAULT NULL COMMENT 'Hash key for a cached fieldvalues',
  `last_used_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Timestamp of when these FieldValues were last used.',
  PRIMARY KEY (`id`),
  KEY `idx_fieldvalues_field_id` (`field_id`),
  CONSTRAINT `fk_fieldvalues_ref_field_id` FOREIGN KEY (`field_id`) REFERENCES `metabase_field` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_table` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `name` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `entity_type` varchar(254) DEFAULT NULL,
  `active` bit(1) NOT NULL,
  `db_id` int(11) NOT NULL,
  `display_name` varchar(256) DEFAULT NULL,
  `visibility_type` varchar(254) DEFAULT NULL,
  `schema` varchar(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `points_of_interest` longtext DEFAULT NULL,
  `caveats` longtext DEFAULT NULL,
  `show_in_getting_started` bit(1) NOT NULL DEFAULT b'0',
  `field_order` varchar(254) NOT NULL DEFAULT 'database',
  `initial_sync_status` varchar(32) NOT NULL DEFAULT 'complete' COMMENT 'String indicating whether a table has completed its initial sync and is ready to use',
  `is_upload` bit(1) NOT NULL DEFAULT b'0',
  `database_require_filter` bit(1) DEFAULT NULL,
  `estimated_row_count` bigint(20) DEFAULT NULL COMMENT 'The estimated row count',
  `view_count` int(11) NOT NULL DEFAULT 0 COMMENT 'Keeps a running count of card views',
  `is_defective_duplicate` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Indicates whether the table is a defective duplicate that should never have been created.',
  `unique_table_helper` varchar(254) GENERATED ALWAYS AS (case when `is_defective_duplicate` = 1 then NULL else coalesce(`schema`,'') end) STORED,
  `deactivated_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the table was deactivated (active changed from true to false)',
  `archived_at` timestamp(6) NULL DEFAULT NULL COMMENT 'The timestamp when the table was marked for archiving',
  `is_writable` bit(1) DEFAULT NULL COMMENT 'true if current connection can insert, update and delete rows from this table',
  `data_authority` varchar(20) NOT NULL DEFAULT 'unconfigured' COMMENT 'Indicates the data authority status - unconfigured, authoritative, computed, or ingested',
  `data_source` varchar(254) DEFAULT NULL COMMENT 'The origin type of the data (e.g. metabase-transform)',
  `data_layer` varchar(254) DEFAULT 'internal' COMMENT 'The (new) enum for visibility class',
  `owner_email` longtext DEFAULT NULL COMMENT 'An optional email address of the ''owner'' of this table, exclusive with owner_user_id.',
  `owner_user_id` int(11) DEFAULT NULL COMMENT 'An (metabase) user id of the ''owner'' of this table, exclusive with owner_email.',
  `collection_id` int(11) DEFAULT NULL COMMENT 'The collection this table is published to (null if not published or published to root)',
  `is_published` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this table is published',
  `transform_id` int(11) DEFAULT NULL COMMENT 'Foreign key to the transform that created this table',
  `transform_target` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether any transform is configured to target this table. Conservative: eagerly set to true when a transform targets this table (never stale in this direction), cleared asynchronously when no transforms reference it anymore (may have false positives, never false negatives).',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_uniq_table_db_id_schema_name` (`db_id`,`schema`,`name`),
  UNIQUE KEY `idx_unique_table` (`db_id`,`name`,`unique_table_helper`),
  KEY `idx_table_db_id` (`db_id`),
  KEY `idx_metabase_table_show_in_getting_started` (`show_in_getting_started`),
  KEY `idx_metabase_table_db_id_schema` (`db_id`,`schema`),
  KEY `idx_metabase_table_collection_id` (`collection_id`),
  KEY `idx_metabase_table_transform_id` (`transform_id`),
  CONSTRAINT `fk_metabase_table_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`),
  CONSTRAINT `fk_metabase_table_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_table_ref_database_id` FOREIGN KEY (`db_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `metabase_table_import` (
  `source_id` int(11) NOT NULL COMMENT 'Wire :id — source appdb''s metabase_table.id. Unique within one file.',
  `source_db_id` int(11) NOT NULL COMMENT 'Wire :db_id — references the source-side database row in :databases[].',
  `db_name` varchar(254) NOT NULL COMMENT 'Denormalized from :databases[] at drain time, used for natural-key match against target.',
  `schema` varchar(254) DEFAULT NULL COMMENT 'Mirrors metabase_table.schema nullability.',
  `name` varchar(254) NOT NULL COMMENT 'Wire :name — table''s natural-key name component.',
  `description` longtext DEFAULT NULL COMMENT 'Wire :description — clobbered onto metabase_table.description on merge.',
  `display_name` varchar(254) DEFAULT NULL COMMENT 'Pre-humanized at drain time so the merge SQL doesn''t replicate the algorithm in three dialects.',
  `target_id` int(11) DEFAULT NULL COMMENT 'Resolved by table-resolve step; → metabase_table.id. NULL means no live row matches; row is an insert candidate.',
  PRIMARY KEY (`source_id`),
  KEY `idx_mti_target_id` (`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Staging table for the metadata file importer''s tables phase. Drained outside the merge txn, merged into metabase_table inside it.';
--;;
CREATE TABLE `metabot` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(254) NOT NULL COMMENT 'The name of the metabot',
  `description` longtext DEFAULT NULL COMMENT 'Description of the metabot',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the metabot was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the metabot was updated',
  `use_verified_content` bit(1) DEFAULT b'0' COMMENT 'Whether this metabot should only use verified content',
  `collection_id` int(11) DEFAULT NULL COMMENT 'ID of the collection this metabot can access',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot configuration';
--;;
INSERT INTO `metabot` (`id`, `name`, `description`, `entity_id`, `created_at`, `updated_at`, `use_verified_content`, `collection_id`) VALUES (1,'Metabot','Metabot instance for internal users.','metabotmetabotmetabot','2026-08-15 04:37:04.000000','2026-08-15 04:37:04.000000','\0',NULL);
