INSERT INTO `metabot` (`id`, `name`, `description`, `entity_id`, `created_at`, `updated_at`, `use_verified_content`, `collection_id`) VALUES (2,'Embedded Metabot','Metabot instance for embedded metabase users.','embeddedmetabotmetabo','2026-08-15 04:37:04.000000','2026-08-15 04:37:04.000000','\0',NULL);
--;;
CREATE TABLE `metabot_conversation` (
  `id` varchar(36) NOT NULL COMMENT 'Conversation UUID',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'created_at',
  `user_id` int(11) NOT NULL COMMENT 'Reference to user having the conversation',
  `summary` longtext DEFAULT NULL COMMENT 'Auto-generated summary for the conversation',
  `state` longtext DEFAULT NULL COMMENT 'Metabot conversation state',
  `ip_address` varchar(45) DEFAULT NULL COMMENT 'Client IP captured at conversation creation; NULL for Slack-originated conversations.',
  `slack_team_id` varchar(255) DEFAULT NULL COMMENT 'Slack workspace team ID for Slack-originated Metabot conversations',
  `slack_channel_id` varchar(255) DEFAULT NULL COMMENT 'Slack channel ID for Slack-originated Metabot conversations',
  `slack_thread_ts` varchar(255) DEFAULT NULL COMMENT 'Slack root thread timestamp for Slack-originated Metabot conversations',
  `embedding_hostname` varchar(512) DEFAULT NULL COMMENT 'Hostname extracted from the embed referrer header at conversation creation. Always populated when an embed referrer is present.',
  `embedding_path` varchar(2048) DEFAULT NULL COMMENT 'Path extracted from the embed referrer header at conversation creation, PII.',
  `user_agent` varchar(512) DEFAULT NULL COMMENT 'Raw User-Agent header captured at conversation creation, PII.',
  `sanitized_user_agent` varchar(512) DEFAULT NULL COMMENT 'Sanitized User-Agent string (browser + OS family) at the originating conversation, for analytics display.',
  PRIMARY KEY (`id`),
  KEY `idx_metabot_conversation_user_id` (`user_id`),
  KEY `idx_metabot_conversation_created_at` (`created_at`),
  CONSTRAINT `fk_metabot_conversation_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store metabot conversation messages';
--;;
CREATE TABLE `metabot_feedback` (
  `message_id` int(11) NOT NULL COMMENT 'PK + FK to metabot_message.id — enforces 1:1',
  `positive` bit(1) NOT NULL COMMENT 'true = thumbs up, false = thumbs down',
  `issue_type` varchar(64) DEFAULT NULL COMMENT 'Optional structured issue category (e.g. "ui-bug", "not-factual")',
  `freeform_feedback` longtext DEFAULT NULL COMMENT 'Optional freeform comment',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the feedback was submitted',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the feedback was last updated',
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate PK',
  `user_id` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_feedback_message_id_user_id` (`message_id`,`user_id`),
  CONSTRAINT `fk_metabot_feedback_message_id` FOREIGN KEY (`message_id`) REFERENCES `metabot_message` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User feedback - positive/negative w/ optional reason + comment';
--;;
CREATE TABLE `metabot_group_limit` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL COMMENT 'The ID of the associated permissions group',
  `max_usage` int(11) NOT NULL COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting',
  PRIMARY KEY (`id`),
  UNIQUE KEY `group_id` (`group_id`),
  CONSTRAINT `fk_metabot_group_limit_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot usage limits per group';
--;;
CREATE TABLE `metabot_instance_limit` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tenant_id` int(11) DEFAULT NULL COMMENT 'The tenant ID, or null for instance-wide limit',
  `max_usage` int(11) DEFAULT NULL COMMENT 'The maximum usage value, interpreted according to the metabot-limit-unit setting. Null is unlimited',
  PRIMARY KEY (`id`),
  UNIQUE KEY `tenant_id` (`tenant_id`),
  CONSTRAINT `fk_metabot_instance_limit_ref_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenant` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Metabot usage limits at the instance or tenant level';
--;;
CREATE TABLE `metabot_message` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Autoincrement PK',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'created_at',
  `profile_id` longtext NOT NULL COMMENT 'ai-service profile used to perform the conversation',
  `role` varchar(20) NOT NULL COMMENT 'Role of the sender',
  `data` longtext NOT NULL COMMENT 'Full message content',
  `usage` longtext DEFAULT NULL COMMENT 'Can be null for user messages; {"<model-name>": {"prompt": 1, "completion": 2}}',
  `total_tokens` int(11) NOT NULL COMMENT 'A sum of all prompt+completion from `usage`',
  `conversation_id` varchar(36) NOT NULL COMMENT 'Reference to a conversation',
  `slack_msg_id` varchar(255) DEFAULT NULL COMMENT 'Slack message ID (ts) for correlating with Slack thread history',
  `channel_id` varchar(255) DEFAULT NULL COMMENT 'Slack channel ID for correlating Slack responses',
  `deleted_at` timestamp(6) NULL DEFAULT NULL COMMENT 'Soft delete timestamp for removed Slack metabot responses',
  `deleted_by_user_id` int(11) DEFAULT NULL COMMENT 'Metabase user ID who removed the Slack metabot response',
  `user_id` int(11) DEFAULT NULL COMMENT 'Metabase user ID associated with this message',
  `ai_proxied` bit(1) DEFAULT NULL COMMENT 'Whether this message was routed through the Metabase Cloud AI proxy (true) or directly via BYOK keys (false). Null for messages created before this migration.',
  `external_id` varchar(36) DEFAULT NULL COMMENT 'Stable id shared with clients and used to resolve feedback submissions',
  `finished` bit(1) DEFAULT b'1' COMMENT 'NULL while in flight, true once completed, false if the client aborted mid-stream.',
  `error` longtext DEFAULT NULL COMMENT 'Error payload from the agent''s error stream part.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metabot_message_external_id` (`external_id`),
  KEY `idx_metabot_message_conversation_id` (`conversation_id`),
  KEY `idx_metabot_message_channel_id_slack_msg_id` (`channel_id`,`slack_msg_id`),
  KEY `idx_metabot_message_user_id_conversation_id` (`user_id`,`conversation_id`),
  CONSTRAINT `fk_metabot_message_conversation_id` FOREIGN KEY (`conversation_id`) REFERENCES `metabot_conversation` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to store metabot conversation messages';
--;;
CREATE TABLE `metabot_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `group_id` int(11) NOT NULL COMMENT 'The ID of the associated permissions group',
  `perm_type` varchar(254) NOT NULL COMMENT 'The type of permission',
  `perm_value` varchar(254) NOT NULL COMMENT 'The value of the permission',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_metabot_permissions_group_id_perm_type` (`group_id`,`perm_type`),
  KEY `idx_metabot_permissions_group_id` (`group_id`),
  CONSTRAINT `fk_metabot_permissions_ref_permissions_group` FOREIGN KEY (`group_id`) REFERENCES `permissions_group` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A table to store metabot permissions per permissions group';
--;;
