CREATE TABLE `source_dimension_daily` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) NOT NULL COMMENT 'Owning source kind for the dimension fact',
  `source_id` int(11) NOT NULL COMMENT 'Owning table or card ID for the dimension fact',
  `ownership_mode` varchar(254) NOT NULL COMMENT 'Ownership attribution mode for the dimension fact',
  `field_id` int(11) NOT NULL COMMENT 'Breakout field referenced by the dimension fact',
  `temporal_unit` varchar(254) DEFAULT NULL COMMENT 'Temporal bucketing unit for temporal breakouts when applicable',
  `binning` longtext DEFAULT NULL COMMENT 'Canonical serialized binning configuration when applicable',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int(11) NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_dimension_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_dimension_daily_field` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped dimension usage rollups';
--;;
CREATE TABLE `source_dimension_profile_daily` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) NOT NULL COMMENT 'Owning source kind for the profiled dimension',
  `source_id` int(11) NOT NULL COMMENT 'Owning table or card ID for the profiled dimension',
  `field_id` int(11) NOT NULL COMMENT 'Field being profiled',
  `source_basis` varchar(254) NOT NULL COMMENT 'Provenance of the profile signal such as fingerprint',
  `observation_type` varchar(254) NOT NULL COMMENT 'Kind of profile observation such as single-value or all-null',
  `observation_value` longtext DEFAULT NULL COMMENT 'Optional serialized value associated with the profile observation',
  `bucket_date` date NOT NULL COMMENT 'UTC day when the profile observation was recorded',
  `count` int(11) NOT NULL COMMENT 'Number of times the observation was recorded on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_dimension_profile_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`),
  KEY `idx_source_dimension_profile_daily_field` (`field_id`,`observation_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped dimension profile observations';
--;;
CREATE TABLE `source_metric_daily` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int(11) DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(254) NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `agg_type` varchar(254) NOT NULL COMMENT 'Aggregation operator for the metric fact',
  `agg_field_id` int(11) DEFAULT NULL COMMENT 'Aggregated field referenced by the metric fact when applicable',
  `temporal_field_id` int(11) DEFAULT NULL COMMENT 'Breakout field supplying temporal context for the metric fact when applicable',
  `temporal_unit` varchar(254) DEFAULT NULL COMMENT 'Temporal bucketing unit associated with the metric fact when applicable',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int(11) NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_metric_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_metric_daily_agg` (`agg_type`,`agg_field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped metric usage rollups';
--;;
CREATE TABLE `source_replacement_run` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `source_entity_type` varchar(50) NOT NULL COMMENT 'Type of the source entity (card or table)',
  `source_entity_id` int(11) NOT NULL COMMENT 'ID of the source entity',
  `target_entity_type` varchar(50) NOT NULL COMMENT 'Type of the target entity (card or table)',
  `target_entity_id` int(11) NOT NULL COMMENT 'ID of the target entity',
  `status` varchar(50) NOT NULL COMMENT 'Current status (started, succeeded, failed, canceled, timeout)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running replacements, null for completed',
  `progress` float DEFAULT NULL COMMENT 'Progress from 0.0 to 1.0',
  `message` longtext DEFAULT NULL COMMENT 'Human-readable message; may contain error info',
  `user_id` int(11) DEFAULT NULL COMMENT 'User who initiated the replacement',
  `start_time` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the replacement started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the replacement completed (null if still running)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_active_source_replacement_run` (`is_active`),
  KEY `idx_source_replacement_run_user_id` (`user_id`),
  KEY `idx_source_replacement_run_source_entity` (`source_entity_type`,`source_entity_id`),
  KEY `idx_source_replacement_run_target_entity` (`target_entity_type`,`target_entity_id`),
  CONSTRAINT `fk_source_replacement_run_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track source replacement executions and their status';
--;;
CREATE TABLE `source_segment_composite_daily` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(256) DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int(11) DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(256) NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `clause` longtext NOT NULL COMMENT 'Canonical serialized representation of the whole :and filter clause',
  `atom_fingerprints` longtext NOT NULL COMMENT 'Sorted JSON array of canonical serialized atom clauses contained in the basket',
  `atom_count` int(11) NOT NULL COMMENT 'Number of atomic predicates in the basket',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int(11) NOT NULL COMMENT 'Number of observations for this composite fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_segment_composite_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped composite segment usage rollups (whole :and baskets)';
--;;
CREATE TABLE `source_segment_daily` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Surrogate primary key',
  `source_type` varchar(254) DEFAULT NULL COMMENT 'Owning source kind for direct or projected facts, or null for canonical mixed facts',
  `source_id` int(11) DEFAULT NULL COMMENT 'Owning table or card ID for direct or projected facts, or null for canonical mixed facts',
  `ownership_mode` varchar(254) NOT NULL COMMENT 'Ownership attribution mode such as direct, projected, or mixed',
  `field_id` int(11) DEFAULT NULL COMMENT 'Field referenced by the segment fact when applicable',
  `predicate` longtext NOT NULL COMMENT 'Canonical serialized representation of the atomic segment predicate',
  `bucket_date` date NOT NULL COMMENT 'UTC day covered by the rollup row',
  `count` int(11) NOT NULL COMMENT 'Number of observations for this fact on the bucket day',
  PRIMARY KEY (`id`),
  KEY `idx_source_segment_daily_bucket_source` (`bucket_date`,`source_type`,`source_id`,`ownership_mode`),
  KEY `idx_source_segment_daily_field` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Daily source-scoped segment usage rollups';
--;;
CREATE TABLE `sso_relay_state` (
  `id` varchar(128) NOT NULL COMMENT 'SHA-512 hash of the RelayState key',
  `continue_url` longtext NOT NULL COMMENT 'URL the popup falls back to when there is no opener window',
  `origin` varchar(254) DEFAULT NULL COMMENT 'Origin used as the postMessage target when handing the session back to the opener (embedding only)',
  `embedding` bit(1) NOT NULL DEFAULT b'0' COMMENT 'Whether this is a modular-embedding popup login (postMessage handback) vs. a regular redirect login',
  `expires_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'When this RelayState entry expires and is no longer valid',
  `created_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'When this RelayState entry was created',
  PRIMARY KEY (`id`),
  KEY `idx_sso_relay_state_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Server-side store for SAML SSO RelayState context';
--;;
CREATE TABLE `support_access_grant_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique identifier for the grant',
  `user_id` int(11) DEFAULT NULL COMMENT 'ID of the admin user who created this grant',
  `ticket_number` varchar(100) DEFAULT NULL COMMENT 'Support ticket number associated with this grant',
  `notes` varchar(255) DEFAULT NULL COMMENT 'Additional notes associated with this grant',
  `grant_start_timestamp` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'When the grant becomes active (UTC)',
  `grant_end_timestamp` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'When the grant expires (UTC)',
  `revoked_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the grant was manually revoked (UTC), null if not revoked',
  `revoked_by_user_id` int(11) DEFAULT NULL COMMENT 'ID of the admin user who revoked this grant',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this record was created (UTC)',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this record was last updated (UTC)',
  PRIMARY KEY (`id`),
  KEY `idx_support_access_grant_log_user_id` (`user_id`),
  KEY `idx_support_access_grant_log_revoked_by_user_id` (`revoked_by_user_id`),
  KEY `idx_support_access_grant_log_active` (`grant_end_timestamp`,`revoked_at`),
  CONSTRAINT `fk_support_access_grant_log_revoked_by_user_id` FOREIGN KEY (`revoked_by_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_support_access_grant_log_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Store support access grant requests and their lifecycle for audit purposes';
--;;
CREATE TABLE `table_privileges` (
  `table_id` int(11) NOT NULL COMMENT 'Table ID',
  `role` varchar(255) DEFAULT NULL COMMENT 'Role name. NULL indicates the privileges are the current user''s',
  `select` bit(1) NOT NULL DEFAULT b'0',
  `update` bit(1) NOT NULL DEFAULT b'0',
  `insert` bit(1) NOT NULL DEFAULT b'0',
  `delete` bit(1) NOT NULL DEFAULT b'0',
  KEY `fk_table_privileges_table_id` (`table_id`),
  KEY `idx_table_privileges_role` (`role`),
  CONSTRAINT `fk_table_privileges_table_id` FOREIGN KEY (`table_id`) REFERENCES `metabase_table` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table for user and role privileges by table';
--;;
CREATE TABLE `table_remapping` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `database_id` int(11) NOT NULL COMMENT 'Database this remapping applies to',
  `from_db` varchar(254) NOT NULL DEFAULT '' COMMENT 'Source database/project (top-level identifier; e.g. BigQuery project, ClickHouse db). Empty string when driver does not emit this level.',
  `from_schema` varchar(254) NOT NULL DEFAULT '' COMMENT 'Source schema name. Empty string for schema-less drivers.',
  `from_table_name` varchar(254) NOT NULL COMMENT 'Source table name',
  `to_db` varchar(254) NOT NULL DEFAULT '' COMMENT 'Target database/project (top-level identifier). Empty string when driver does not emit this level.',
  `to_schema` varchar(254) NOT NULL DEFAULT '' COMMENT 'Target schema name. Empty string for schema-less drivers.',
  `to_table_name` varchar(254) NOT NULL COMMENT 'Target table name',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this remapping was created',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_table_remapping_source` (`database_id`,`from_db`,`from_schema`,`from_table_name`),
  UNIQUE KEY `idx_unique_table_remapping_target` (`database_id`,`to_db`,`to_schema`,`to_table_name`),
  CONSTRAINT `fk_table_remapping_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Maps production tables to workspace tables for query remapping';
--;;
CREATE TABLE `task_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task` varchar(254) NOT NULL COMMENT 'Name of the task',
  `db_id` int(11) DEFAULT NULL,
  `started_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  `ended_at` timestamp(6) NULL DEFAULT NULL,
  `duration` int(11) DEFAULT NULL,
  `task_details` longtext DEFAULT NULL,
  `status` varchar(21) NOT NULL DEFAULT 'started' COMMENT 'the status of task history, could be started, failed, success, unknown',
  `run_id` int(11) DEFAULT NULL COMMENT 'FK to task_run - groups tasks belonging to the same run',
  `logs` longtext DEFAULT NULL COMMENT 'JSON array of captured log messages during task execution',
  PRIMARY KEY (`id`),
  KEY `idx_task_history_end_time` (`ended_at`),
  KEY `idx_task_history_db_id` (`db_id`),
  KEY `idx_task_history_started_at` (`started_at`),
  KEY `idx_task_history_run_id` (`run_id`),
  CONSTRAINT `fk_task_history_run_id` FOREIGN KEY (`run_id`) REFERENCES `task_run` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timing and metadata info about background/quartz processes';
--;;
CREATE TABLE `task_run` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `run_type` varchar(32) NOT NULL COMMENT 'Type of run: subscription, alert, sync, fingerprint',
  `entity_type` varchar(32) NOT NULL COMMENT 'Type of associated entity: database, card, dashboard',
  `entity_id` int(11) NOT NULL COMMENT 'ID of associated entity',
  `started_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the run started',
  `ended_at` timestamp(6) NULL DEFAULT NULL COMMENT 'When the run completed (null if still running)',
  `status` varchar(21) NOT NULL COMMENT 'Overall status: started, success, failed',
  `process_uuid` varchar(36) NOT NULL DEFAULT 'unknown' COMMENT 'UUID of the Metabase instance that created this run',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Last heartbeat timestamp - updated periodically for running tasks',
  `notification_id` int(11) DEFAULT NULL COMMENT 'ID of the notification that produced this run (null for non-notification runs, or runs predating this column)',
  PRIMARY KEY (`id`),
  KEY `idx_task_run_type_entity` (`run_type`,`entity_type`,`entity_id`),
  KEY `idx_task_run_started_at` (`started_at`),
  KEY `idx_task_run_notification_id_started_at` (`notification_id`,`started_at`),
  KEY `idx_task_run_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Groups related tasks from a single operation (subscription, alert, sync, fingerprint)';
--;;
CREATE TABLE `tenant` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'the ID of the tenant',
  `name` varchar(254) NOT NULL COMMENT 'the unique name of the tenant',
  `slug` varchar(254) NOT NULL COMMENT 'the slugified version of this tenant''s name',
  `is_active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the tenant is active or not',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'The timestamp of when the tenant was updated',
  `created_at` timestamp(6) NOT NULL DEFAULT '0000-00-00 00:00:00.000000' COMMENT 'The timestamp of when the tenant was created',
  `attributes` longtext DEFAULT NULL COMMENT 'JSON object containing custom tenant attributes',
  `tenant_collection_id` int(11) NOT NULL COMMENT 'The ID of the collection',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tenants (collections of external users). A user can be in exactly zero or one tenants.\n';
--;;
CREATE TABLE `timeline` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Name of the timeline',
  `description` varchar(255) DEFAULT NULL COMMENT 'Optional description of the timeline',
  `icon` varchar(128) NOT NULL,
  `collection_id` int(11) DEFAULT NULL COMMENT 'ID of the collection containing the timeline',
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `creator_id` int(11) NOT NULL COMMENT 'ID of the user who created the timeline',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the timeline was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the timeline was updated',
  `default` bit(1) NOT NULL DEFAULT b'0',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_timeline_creator_id` (`creator_id`),
  KEY `idx_timeline_collection_id` (`collection_id`),
  CONSTRAINT `fk_timeline_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_timeline_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Timeline table to organize events';
--;;
CREATE TABLE `timeline_event` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `timeline_id` int(11) NOT NULL COMMENT 'ID of the timeline containing the event',
  `name` varchar(255) NOT NULL COMMENT 'Name of the event',
  `description` varchar(255) DEFAULT NULL COMMENT 'Optional markdown description of the event',
  `timestamp` timestamp(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT 'When the event happened',
  `time_matters` bit(1) NOT NULL,
  `timezone` varchar(255) NOT NULL COMMENT 'Timezone to display the underlying UTC timestamp in for the client',
  `icon` varchar(128) NOT NULL,
  `archived` bit(1) NOT NULL DEFAULT b'0',
  `creator_id` int(11) NOT NULL COMMENT 'ID of the user who created the event',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the event was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the event was modified',
  PRIMARY KEY (`id`),
  KEY `fk_event_creator_id` (`creator_id`),
  KEY `idx_timeline_event_timeline_id` (`timeline_id`),
  KEY `idx_timeline_event_timeline_id_timestamp` (`timeline_id`,`timestamp`),
  CONSTRAINT `fk_event_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_events_timeline_id` FOREIGN KEY (`timeline_id`) REFERENCES `timeline` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Events table';
--;;
CREATE TABLE `transform` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext NOT NULL COMMENT 'Name',
  `description` longtext DEFAULT NULL COMMENT 'the description of the transform',
  `source` longtext NOT NULL COMMENT 'JSON of source',
  `target` longtext NOT NULL COMMENT 'JSON of target',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the transform was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp of when the transform was updated',
  `source_type` varchar(32) NOT NULL,
  `creator_id` int(11) NOT NULL DEFAULT 13371338 COMMENT 'User who created this transform',
  `source_database_id` int(11) DEFAULT NULL,
  `collection_id` int(11) DEFAULT NULL COMMENT 'The collection the transform is in',
  `owner_user_id` int(11) DEFAULT NULL COMMENT 'The user ID of the owner of this transform (can be different from creator)',
  `owner_email` longtext DEFAULT NULL COMMENT 'An optional email address of the owner of this transform (for external owners), exclusive with owner_user_id',
  `target_db_id` int(11) DEFAULT NULL COMMENT 'Target database ID for the transform output',
  `last_checkpoint_value` longtext DEFAULT NULL COMMENT 'Serialized checkpoint watermark value for incremental transforms, temporal as ISO8601',
  `target_table_id` int(11) DEFAULT NULL COMMENT 'FK to metabase_table for the transform''s target table',
  `table_dependencies` longtext DEFAULT NULL COMMENT 'Precomputed table dependencies (JSON) used for execution ordering and cycle detection. Null means not yet computed.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `idx_transform_creator_id` (`creator_id`),
  KEY `idx_transform_source_database_id` (`source_database_id`),
  KEY `idx_transform_collection_id` (`collection_id`),
  KEY `idx_transform_owner_user_id` (`owner_user_id`),
  KEY `idx_transform_target_db_id` (`target_db_id`),
  KEY `idx_transform_target_table_id` (`target_table_id`),
  CONSTRAINT `fk_tranform_source_database_id` FOREIGN KEY (`source_database_id`) REFERENCES `metabase_database` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_collection_id` FOREIGN KEY (`collection_id`) REFERENCES `collection` (`id`),
  CONSTRAINT `fk_transform_owner_user_id` FOREIGN KEY (`owner_user_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_ref_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_target_db_id` FOREIGN KEY (`target_db_id`) REFERENCES `metabase_database` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transform_target_table_id` FOREIGN KEY (`target_table_id`) REFERENCES `metabase_table` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='The main table for Transform entities';
--;;
CREATE TABLE `transform_job` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` longtext NOT NULL COMMENT 'The name of the transform job.',
  `description` longtext DEFAULT NULL COMMENT 'A description of the transform job.',
  `schedule` longtext NOT NULL COMMENT 'Cron expression for job schedule',
  `entity_id` char(21) DEFAULT NULL COMMENT 'NanoID identifier for the job',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job was last updated.',
  `built_in_type` varchar(255) DEFAULT NULL COMMENT 'Type of the built-in transform job: hourly, daily, weekly, monthly.',
  `ui_display_type` varchar(32) NOT NULL DEFAULT 'cron/raw' COMMENT 'The display type of the schedule, used for the UI only; "cron/raw" or "cron/builder".',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT 'Whether the job is active. Inactive jobs do not run on schedule.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Jobs that execute transforms based on tags';
--;;
INSERT INTO `transform_job` (`id`, `name`, `description`, `schedule`, `entity_id`, `created_at`, `updated_at`, `built_in_type`, `ui_display_type`, `active`) VALUES (1,'Hourly job','Executes transforms tagged with \'hourly\' every hour','0 0 * * * ? *','RognTgBT2fXaxoQh4ws7z','2026-08-15 04:37:05.747837','2026-08-15 04:37:05.747837','hourly','cron/builder','');
--;;
INSERT INTO `transform_job` (`id`, `name`, `description`, `schedule`, `entity_id`, `created_at`, `updated_at`, `built_in_type`, `ui_display_type`, `active`) VALUES (2,'Daily job','Executes transforms tagged with \'daily\' once per day','0 0 0 * * ? *','PJahvcoF61oX5T4uCT_FY','2026-08-15 04:37:05.747837','2026-08-15 04:37:05.747837','daily','cron/builder','');
--;;
INSERT INTO `transform_job` (`id`, `name`, `description`, `schedule`, `entity_id`, `created_at`, `updated_at`, `built_in_type`, `ui_display_type`, `active`) VALUES (3,'Weekly job','Executes transforms tagged with \'weekly\' once per week','0 0 0 ? * 1 *','lXIFa2SUrXLgaLZJx33oU','2026-08-15 04:37:05.747837','2026-08-15 04:37:05.747837','weekly','cron/builder','');
--;;
INSERT INTO `transform_job` (`id`, `name`, `description`, `schedule`, `entity_id`, `created_at`, `updated_at`, `built_in_type`, `ui_display_type`, `active`) VALUES (4,'Monthly job','Executes transforms tagged with \'monthly\' once per month','0 0 0 1 * ? *','CL1TVitmzJrDjdjvO2xmN','2026-08-15 04:37:05.747837','2026-08-15 04:37:05.747837','monthly','cron/builder','');
--;;
CREATE TABLE `transform_job_run` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `job_id` bigint(20) NOT NULL COMMENT 'Identifier for the transform job',
  `run_method` varchar(255) NOT NULL COMMENT 'Method used to execute the transform job',
  `status` varchar(50) NOT NULL COMMENT 'Current status of the transform job (running, completed, failed, etc.)',
  `is_active` bit(1) DEFAULT NULL COMMENT 'True only for currently running jobs, null for the others',
  `start_time` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When the transform job started',
  `end_time` timestamp(6) NULL DEFAULT NULL COMMENT 'When the tranform job completed (null if still running)',
  `message` longtext DEFAULT NULL COMMENT 'Human-readable message about the run; may contain error message in case status is error',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job run was created.',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'The timestamp this transform job run was last updated.',
  `last_heartbeat` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'Heartbeat timestamp stamped periodically while the run executes; a stale value means the owning process died',
  PRIMARY KEY (`id`),
  KEY `idx_transform_job_run_active_runs` (`is_active`,`last_heartbeat`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table to track transform job executions and their status in the app database';
--;;
CREATE TABLE `transform_job_transform_tag` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `job_id` int(11) NOT NULL COMMENT 'The id of the transform job.',
  `tag_id` int(11) NOT NULL COMMENT 'The id of the transform tag.',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  `position` int(11) NOT NULL COMMENT 'The ordering position of this tag for the job.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_job_tag` (`job_id`,`tag_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_transform_job_transform_tag_tag_id` (`tag_id`),
  CONSTRAINT `fk_transform_job_transform_tag_job_id` FOREIGN KEY (`job_id`) REFERENCES `transform_job` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_job_transform_tag_tag_id` FOREIGN KEY (`tag_id`) REFERENCES `transform_tag` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table for jobs and tags';
--;;
