CREATE TABLE `transform_transform_tag` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `transform_id` int(11) NOT NULL COMMENT 'The id of the transform.',
  `tag_id` int(11) NOT NULL COMMENT 'The id of the tag.',
  `entity_id` char(21) DEFAULT NULL COMMENT 'Random NanoID tag for unique identity.',
  `position` int(11) NOT NULL COMMENT 'The relative UI ordering of this tag on the transform',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_transform_tag` (`transform_id`,`tag_id`),
  UNIQUE KEY `entity_id` (`entity_id`),
  KEY `fk_transform_transform_tag_tag_id` (`tag_id`),
  CONSTRAINT `fk_transform_transform_tag_tag_id` FOREIGN KEY (`tag_id`) REFERENCES `transform_tag` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_transform_transform_tag_transform_id` FOREIGN KEY (`transform_id`) REFERENCES `transform` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Join table for transforms and tags';
--;;
CREATE TABLE `user_key_value` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT 'The ID of the user this KV-pair is for',
  `namespace` varchar(254) NOT NULL COMMENT 'The namespace for this KV, e.g. "dashboard-filters" or "nobody-knows"',
  `key` varchar(254) NOT NULL COMMENT 'The key',
  `value` longtext DEFAULT NULL COMMENT 'The value, serialized JSON',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this row was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this row was last updated',
  `expires_at` timestamp(6) NULL DEFAULT NULL COMMENT 'If set, when this row expires',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_key_value_user_id_namespace_key` (`user_id`,`namespace`,`key`),
  CONSTRAINT `fk_user_key_value_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='A simple key value store for each user.';
--;;
CREATE TABLE `user_parameter_value` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT 'ID of the User who has set the parameter value',
  `parameter_id` varchar(36) NOT NULL COMMENT 'The parameter ID',
  `value` longtext DEFAULT NULL COMMENT 'Value of the parameter',
  `dashboard_id` int(11) DEFAULT NULL COMMENT 'The ID of the dashboard',
  PRIMARY KEY (`id`),
  KEY `idx_user_parameter_value_user_id` (`user_id`),
  KEY `idx_user_parameter_value_dashboard_id` (`dashboard_id`),
  KEY `idx_user_parameter_value_user_id_dashboard_id_parameter_id` (`user_id`,`dashboard_id`,`parameter_id`),
  CONSTRAINT `fk_user_parameter_value_dashboard_id` FOREIGN KEY (`dashboard_id`) REFERENCES `report_dashboard` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_parameter_value_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Table holding last set value of a parameter per user';
--;;
CREATE TABLE `view_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `model` varchar(16) NOT NULL,
  `model_id` int(11) NOT NULL,
  `timestamp` timestamp(6) NULL DEFAULT NULL,
  `metadata` longtext DEFAULT NULL,
  `has_access` bit(1) DEFAULT NULL,
  `context` varchar(32) DEFAULT NULL COMMENT 'The context of the view, can be collection, question, or dashboard. Only for cards.',
  `embedding_client` varchar(254) DEFAULT NULL COMMENT 'Used by the embedding team to track SDK usage',
  `embedding_sdk_version` varchar(254) DEFAULT NULL,
  `auth_method` varchar(32) DEFAULT NULL COMMENT 'Authentication method used (e.g. jwt, saml, api-key, public, guest, etc.)',
  `tenant_id` int(11) DEFAULT NULL COMMENT 'Tenant ID of the user who generated this view',
  `embedding_hostname` varchar(512) DEFAULT NULL COMMENT 'Hostname from Origin header, PII',
  `embedding_path` varchar(2048) DEFAULT NULL COMMENT 'Path from Referer header (query params stripped), PII',
  `user_agent` varchar(512) DEFAULT NULL COMMENT 'User-Agent header, PII',
  `ip_address` varchar(45) DEFAULT NULL COMMENT 'Client IP address, PII',
  `sanitized_user_agent` varchar(512) DEFAULT NULL COMMENT 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII',
  `embedding_route` varchar(64) DEFAULT NULL COMMENT 'API route surface (e.g. public, guest-embed, metabot, agent-api)',
  `metabase_version` varchar(32) DEFAULT NULL COMMENT 'Metabase server version tag at time of insert',
  PRIMARY KEY (`id`),
  KEY `idx_view_log_user_id` (`user_id`),
  KEY `idx_view_log_model_id` (`model_id`),
  KEY `idx_view_log_timestamp` (`timestamp`),
  KEY `idx_view_log_tenant_id` (`tenant_id`),
  CONSTRAINT `fk_view_log_ref_user_id` FOREIGN KEY (`user_id`) REFERENCES `core_user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--;;
CREATE TABLE `workspace` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `name` varchar(254) NOT NULL COMMENT 'Display name of the workspace',
  `creator_id` int(11) DEFAULT NULL COMMENT 'User who created this workspace',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this workspace was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this workspace was last updated',
  PRIMARY KEY (`id`),
  KEY `idx_workspace_creator_id` (`creator_id`),
  CONSTRAINT `fk_workspace_creator_id` FOREIGN KEY (`creator_id`) REFERENCES `core_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Groups one or more databases with override credentials and per-database schema config';
--;;
CREATE TABLE `workspace_database` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Unique ID',
  `workspace_id` int(11) NOT NULL COMMENT 'The workspace this row belongs to',
  `database_id` int(11) NOT NULL COMMENT 'The underlying database this row configures',
  `database_details` longtext NOT NULL COMMENT 'JSON-encoded override connection details',
  `output_namespace` varchar(254) NOT NULL COMMENT 'Driver-opaque namespace string where workspace output tables are written (schema on Postgres-shaped drivers, database name on MySQL)',
  `input_schemas` longtext NOT NULL COMMENT 'JSON array of input schema names',
  `status` varchar(20) NOT NULL DEFAULT 'unprovisioned' COMMENT 'Provisioning state',
  `created_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this row was created',
  `updated_at` timestamp(6) NOT NULL DEFAULT current_timestamp(6) COMMENT 'When this row was last updated',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_unique_workspace_database` (`workspace_id`,`database_id`),
  KEY `fk_workspace_database_database_id` (`database_id`),
  KEY `idx_workspace_database_workspace_id` (`workspace_id`),
  CONSTRAINT `fk_workspace_database_database_id` FOREIGN KEY (`database_id`) REFERENCES `metabase_database` (`id`),
  CONSTRAINT `fk_workspace_database_workspace_id` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Associates a workspace with a database, with override credentials and schema config';
--;;
CREATE OR REPLACE VIEW `v_ai_usage_log` AS select `a`.`id` AS `usage_log_id`,`a`.`created_at` AS `created_at`,`a`.`source` AS `source`,case `a`.`source` when 'metabot_agent' then 'Metabot' when 'agent' then 'Metabot' when 'document_generate_content' then 'Documents' when 'example_question_generation_batch' then 'Suggested Prompts' when 'slack' then 'Slackbot' when 'slackbot' then 'Slackbot' when 'oss-sql-gen' then 'SQL' when 'sql-gen' then 'SQL' when 'unknown' then 'Unknown' else `a`.`source` end AS `source_name`,`a`.`model` AS `model`,`a`.`profile_id` AS `profile_id`,`a`.`prompt_tokens` AS `prompt_tokens`,`a`.`completion_tokens` AS `completion_tokens`,`a`.`total_tokens` AS `total_tokens`,`a`.`conversation_id` AS `conversation_id`,`a`.`user_id` AS `user_id`,concat('user_',`a`.`user_id`) AS `user_qualified_id`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on(`pg`.`id` = `pgm`.`group_id`)) where `pgm`.`user_id` = `a`.`user_id` and `pg`.`id` <> 1 order by `pg`.`name` limit 1) AS `group_name`,`c`.`ip_address` AS `ip_address`,`c`.`embedding_hostname` AS `embedding_hostname`,`c`.`embedding_path` AS `embedding_path`,`c`.`user_agent` AS `user_agent`,`c`.`sanitized_user_agent` AS `sanitized_user_agent`,`a`.`tenant_id` AS `tenant_id`,`a`.`request_id` AS `request_id`,`a`.`cache_creation_tokens` AS `cache_creation_tokens`,`a`.`cache_read_tokens` AS `cache_read_tokens` from ((`ai_usage_log` `a` left join `core_user` `u` on(`u`.`id` = `a`.`user_id`)) left join `metabot_conversation` `c` on(`c`.`id` = `a`.`conversation_id`));
--;;
CREATE OR REPLACE VIEW `v_alerts` AS with parsed_cron as (select `n`.`id` AS `id`,`ns`.`cron_schedule` AS `cron_schedule`,`ns`.`ui_display_type` AS `ui_display_type`,substring_index(substring_index(`ns`.`cron_schedule`,' ',2),' ',-1) AS `minutes`,substring_index(substring_index(`ns`.`cron_schedule`,' ',3),' ',-1) AS `hours`,substring_index(substring_index(`ns`.`cron_schedule`,' ',4),' ',-1) AS `day_of_month`,substring_index(substring_index(`ns`.`cron_schedule`,' ',6),' ',-1) AS `day_of_week` from (`notification` `n` join `notification_subscription` `ns` on(`n`.`id` = `ns`.`notification_id`)) where `n`.`payload_type` = 'notification/card' and `ns`.`type` = 'notification-subscription/cron'), schedule_info as (select `parsed_cron`.`id` AS `id`,case when `parsed_cron`.`ui_display_type` = 'cron/raw' then 'custom' when `parsed_cron`.`minutes` regexp '^\\*$' or `parsed_cron`.`minutes` regexp '^[0-9]+/[0-9]+$' then 'by the minute' when `parsed_cron`.`day_of_month` <> '*' and (`parsed_cron`.`day_of_week` = '?' or `parsed_cron`.`day_of_week` regexp '^[0-9]#1$' or `parsed_cron`.`day_of_week` regexp '^[0-9]L$') then 'monthly' when `parsed_cron`.`day_of_week` <> '?' and `parsed_cron`.`day_of_week` <> '*' then 'weekly' when `parsed_cron`.`hours` <> '*' then 'daily' else 'hourly' end AS `schedule_type`,case when `parsed_cron`.`day_of_week` regexp '^1' then 'sun' when `parsed_cron`.`day_of_week` regexp '^2' then 'mon' when `parsed_cron`.`day_of_week` regexp '^3' then 'tue' when `parsed_cron`.`day_of_week` regexp '^4' then 'wed' when `parsed_cron`.`day_of_week` regexp '^5' then 'thu' when `parsed_cron`.`day_of_week` regexp '^6' then 'fri' when `parsed_cron`.`day_of_week` regexp '^7' then 'sat' else NULL end AS `schedule_day`,case when `parsed_cron`.`hours` = '*' then NULL when `parsed_cron`.`hours` regexp '^[0-9]+$' then cast(`parsed_cron`.`hours` as signed) when `parsed_cron`.`hours` regexp '^([0-9]+)/[0-9]+$' then cast(substring_index(`parsed_cron`.`hours`,'/',1) as signed) else NULL end AS `schedule_hour` from `parsed_cron`), agg_recipients as (select `nr`.`notification_handler_id` AS `notification_handler_id`,group_concat(`cu`.`email` separator ',') AS `recipients`,group_concat(case when `nr`.`type` = 'notification-recipient/raw-value' then `nr`.`details` else NULL end separator ',') AS `recipient_external` from (`notification_recipient` `nr` left join `core_user` `cu` on(`nr`.`user_id` = `cu`.`id` and `nr`.`type` = 'notification-recipient/user')) group by `nr`.`notification_handler_id`)select `n`.`id` AS `entity_id`,concat('notification_',`n`.`id`) AS `entity_qualified_id`,`n`.`created_at` AS `created_at`,`n`.`updated_at` AS `updated_at`,`n`.`creator_id` AS `creator_id`,`nc`.`card_id` AS `card_id`,concat('card_',`nc`.`card_id`) AS `card_qualified_id`,case when `nc`.`send_condition` = 'has_result' then 'rows' when `nc`.`send_condition` in ('goal_above','goal_below') then 'goal' end AS `alert_condition`,`si`.`schedule_type` AS `schedule_type`,`si`.`schedule_day` AS `schedule_day`,`si`.`schedule_hour` AS `schedule_hour`,`n`.`active` = 0 AS `archived`,`nh`.`channel_type` AS `recipient_type`,`ar`.`recipients` AS `recipients`,`ar`.`recipient_external` AS `recipient_external` from ((((`notification` `n` join `notification_card` `nc` on(`n`.`payload_id` = `nc`.`id`)) join `schedule_info` `si` on(`n`.`id` = `si`.`id`)) left join `notification_handler` `nh` on(`n`.`id` = `nh`.`notification_id`)) left join `agg_recipients` `ar` on(`nh`.`id` = `ar`.`notification_handler_id`)) where `n`.`payload_type` = 'notification/card';
--;;
CREATE OR REPLACE VIEW `v_audit_log` AS (select `audit_log`.`id` AS `id`,case when `audit_log`.`topic` = 'card-create' then 'card-create' when `audit_log`.`topic` = 'card-delete' then 'card-delete' when `audit_log`.`topic` = 'card-update' then 'card-update' when `audit_log`.`topic` = 'pulse-create' then 'subscription-create' when `audit_log`.`topic` = 'pulse-delete' then 'subscription-delete' else `audit_log`.`topic` end AS `topic`,`audit_log`.`timestamp` AS `timestamp`,NULL AS `end_timestamp`,coalesce(`audit_log`.`user_id`,0) AS `user_id`,lcase(`audit_log`.`model`) AS `entity_type`,`audit_log`.`model_id` AS `entity_id`,case when `audit_log`.`model` = 'Dataset' then concat('card_',`audit_log`.`model_id`) when `audit_log`.`model_id` is null then NULL else concat(lcase(`audit_log`.`model`),'_',`audit_log`.`model_id`) end AS `entity_qualified_id`,`audit_log`.`details` AS `details` from `audit_log` where `audit_log`.`topic` not in ('card-read','card-query','dashboard-read','dashboard-query'));
--;;
CREATE OR REPLACE VIEW `v_content` AS select `action`.`id` AS `entity_id`,concat('action_',`action`.`id`) AS `entity_qualified_id`,'action' AS `entity_type`,`action`.`created_at` AS `created_at`,`action`.`updated_at` AS `updated_at`,`action`.`creator_id` AS `creator_id`,`action`.`name` AS `name`,`action`.`description` AS `description`,NULL AS `collection_id`,`action`.`made_public_by_id` AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,`action`.`archived` AS `archived`,`action`.`type` AS `action_type`,`action`.`model_id` AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from `action` union select `collection`.`id` AS `entity_id`,concat('collection_',`collection`.`id`) AS `entity_qualified_id`,'collection' AS `entity_type`,`collection`.`created_at` AS `created_at`,NULL AS `updated_at`,NULL AS `creator_id`,`collection`.`name` AS `name`,`collection`.`description` AS `description`,NULL AS `collection_id`,NULL AS `made_public_by_user`,NULL AS `is_embedding_enabled`,NULL AS `is_verified`,`collection`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,case when `collection`.`authority_level` = 'official' then 1 else 0 end AS `collection_is_official`,case when `collection`.`personal_owner_id` is not null then 1 else 0 end AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from `collection` union select `report_card`.`id` AS `entity_id`,concat('card_',`report_card`.`id`) AS `entity_qualified_id`,`report_card`.`type` AS `entity_type`,`report_card`.`created_at` AS `created_at`,`report_card`.`updated_at` AS `updated_at`,`report_card`.`creator_id` AS `creator_id`,`report_card`.`name` AS `name`,`report_card`.`description` AS `description`,`report_card`.`collection_id` AS `collection_id`,`report_card`.`made_public_by_id` AS `made_public_by_user`,`report_card`.`enable_embedding` AS `is_embedding_enabled`,case when `moderation`.`is_verified` then 1 else 0 end AS `is_verified`,`report_card`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,`report_card`.`display` AS `question_viz_type`,concat('database_',`report_card`.`database_id`) AS `question_database_id`,case when `report_card`.`query_type` = 'native' then 1 else 0 end AS `question_is_native`,NULL AS `event_timestamp` from (`report_card` left join (select concat(`moderation_review`.`moderated_item_type`,'_',`moderation_review`.`moderated_item_id`) AS `entity_qualified_id`,case when `moderation_review`.`status` = 'verified' then 1 else 0 end AS `is_verified` from `moderation_review` where `moderation_review`.`most_recent` <> 0) `moderation` on(concat('card_',`report_card`.`id`) = `moderation`.`entity_qualified_id`)) union select `report_dashboard`.`id` AS `entity_id`,concat('dashboard_',`report_dashboard`.`id`) AS `entity_qualified_id`,'dashboard' AS `entity_type`,`report_dashboard`.`created_at` AS `created_at`,`report_dashboard`.`updated_at` AS `updated_at`,`report_dashboard`.`creator_id` AS `creator_id`,`report_dashboard`.`name` AS `name`,`report_dashboard`.`description` AS `description`,`report_dashboard`.`collection_id` AS `collection_id`,`report_dashboard`.`made_public_by_id` AS `made_public_by_user`,`report_dashboard`.`enable_embedding` AS `is_embedding_enabled`,case when `moderation`.`is_verified` then 1 else 0 end AS `is_verified`,`report_dashboard`.`archived` AS `archived`,NULL AS `action_type`,NULL AS `action_model_id`,NULL AS `collection_is_official`,NULL AS `collection_is_personal`,NULL AS `question_viz_type`,NULL AS `question_database_id`,NULL AS `question_is_native`,NULL AS `event_timestamp` from (`report_dashboard` left join (select concat(`moderation_review`.`moderated_item_type`,'_',`moderation_review