CREATE OR REPLACE VIEW `v_metabot_conversations` AS select `c`.`id` AS `conversation_id`,`c`.`created_at` AS `created_at`,`c`.`user_id` AS `user_id`,`c`.`summary` AS `summary`,coalesce(concat(`u`.`first_name`,' ',`u`.`last_name`),`u`.`email`) AS `user_display_name`,count(`m`.`id`) AS `message_count`,count(case when `m`.`role` = 'user' then 1 end) AS `user_message_count`,count(case when `m`.`role` = 'assistant' then 1 end) AS `assistant_message_count`,coalesce(max(`a`.`total_tokens`),0) AS `total_tokens`,coalesce(max(`a`.`prompt_tokens`),0) AS `prompt_tokens`,coalesce(max(`a`.`completion_tokens`),0) AS `completion_tokens`,max(`m`.`created_at`) AS `last_message_at`,(select `mm`.`profile_id` from `metabot_message` `mm` where `mm`.`conversation_id` = `c`.`id` and `mm`.`role` = 'assistant' and `mm`.`deleted_at` is null order by `mm`.`created_at`,`mm`.`id` limit 1) AS `profile_id`,(select case `mm`.`profile_id` when 'internal' then 'Internal' when 'embedding_next' then 'Embedding' when 'nlq' then 'NLQ' when 'sql' then 'SQL' when 'slackbot' then 'Slackbot' when 'transforms_codegen' then 'Transforms codegen' when 'document-generate-content' then 'Documents' else `mm`.`profile_id` end from `metabot_message` `mm` where `mm`.`conversation_id` = `c`.`id` and `mm`.`role` = 'assistant' and `mm`.`deleted_at` is null order by `mm`.`created_at`,`mm`.`id` limit 1) AS `profile_name`,(select `pg`.`name` from (`permissions_group_membership` `pgm` join `permissions_group` `pg` on(`pg`.`id` = `pgm`.`group_id`)) where `pgm`.`user_id` = `c`.`user_id` and `pg`.`id` <> 1 order by `pg`.`name` limit 1) AS `group_name`,(select `aul`.`source` from `ai_usage_log` `aul` where `aul`.`conversation_id` = `c`.`id` order by `aul`.`created_at` limit 1) AS `source`,(select case `aul`.`source` when 'metabot_agent' then 'Metabot' when 'agent' then 'Metabot' when 'document_generate_content' then 'Documents' when 'example_question_generation_batch' then 'Suggested Prompts' when 'slack' then 'Slackbot' when 'slackbot' then 'Slackbot' when 'oss-sql-gen' then 'SQL' when 'sql-gen' then 'SQL' when 'unknown' then 'Unknown' else `aul`.`source` end from `ai_usage_log` `aul` where `aul`.`conversation_id` = `c`.`id` order by `aul`.`created_at` limit 1) AS `source_name`,`c`.`ip_address` AS `ip_address`,`c`.`embedding_hostname` AS `embedding_hostname`,`c`.`embedding_path` AS `embedding_path`,`c`.`user_agent` AS `user_agent`,`c`.`sanitized_user_agent` AS `sanitized_user_agent`,max(`a`.`tenant_id`) AS `tenant_id`,max(`t`.`name`) AS `tenant_name`,(select `aul`.`model` from `ai_usage_log` `aul` where `aul`.`conversation_id` = `c`.`id` order by `aul`.`created_at` limit 1) AS `model` from ((((`metabot_conversation` `c` left join `core_user` `u` on(`u`.`id` = `c`.`user_id`)) left join `metabot_message` `m` on(`m`.`conversation_id` = `c`.`id` and `m`.`deleted_at` is null)) left join (select `ai_usage_log`.`conversation_id` AS `conversation_id`,coalesce(sum(`ai_usage_log`.`prompt_tokens`),0) AS `prompt_tokens`,coalesce(sum(`ai_usage_log`.`completion_tokens`),0) AS `completion_tokens`,coalesce(sum(`ai_usage_log`.`total_tokens`),0) AS `total_tokens`,min(`ai_usage_log`.`tenant_id`) AS `tenant_id` from `ai_usage_log` where `ai_usage_log`.`conversation_id` is not null group by `ai_usage_log`.`conversation_id`) `a` on(`a`.`conversation_id` = `c`.`id`)) left join `tenant` `t` on(`t`.`id` = `a`.`tenant_id`)) group by `c`.`id`,`c`.`created_at`,`c`.`user_id`,`c`.`summary`,`u`.`first_name`,`u`.`last_name`,`u`.`email`;
